refsection.programlisting:
// Lowpass filter:
[b, a] = ellip(6, 3, 50, 0.6)
// Highpass filter:
[b, a] = ellip(6, 3, 50, 0.6, "high")
// Bandpass filter:
[b, a] = ellip(5, 1, 90, [0.1, 0.2])
// Bandstop filter:
[b, a] = ellip(5, 1, 90, [0.1, 0.2], "stop")
// Zero-pole-gain form:
[z, p, g] = ellip(6, 3, 50, 0.6)
